}
const sections = [
  {id: 'personal', title: 'Мой профиль', icon: Person},
  {id: 'preferences', title: 'Язык и время', icon: Globe},
  {id: 'security', title: 'Безопасность', icon: ShieldCheck},
  {id: 'notifications', title: 'Уведомления', icon: Bell},
